/// The raw `ps -ax -o pid=,lstart=` stdout, or null when ps fails.
Future<String?> processTableSnapshot() =>
    _psOutput(['-ax', '-o', 'pid=,lstart=']);

/// The raw `ps -ax -o pid=,pgid=` stdout, or null when ps fails.
