    }
    final frame = _spinnerFrames[spinnerFrame % _spinnerFrames.length];
    final elapsedSeconds = busyStartedAtMs < 0
        ? 0
        : ((DateTime.now().millisecondsSinceEpoch - busyStartedAtMs) / 1000)
              .floor();
    final label = runStalled
        ? 'Stalled…'
        : (prompt != null
              ? 'Waiting for input…'
