    final quietSeconds = busyLastEventMs < 0
        ? 0
        : ((DateTime.now().millisecondsSinceEpoch - busyLastEventMs) / 1000)
              .floor();
    final suffix = [
      if (busySource.isNotEmpty) '· $busySource',
      if (quietSeconds >= 180) '· quiet ${quietSeconds ~/ 60}m',
    ].join(' ');
