+  final out = <String>[];
+  var depth = 0;
+  var current = '';
+  for (final physical in text.replaceAll('\r\n', '\n').split('\n')) {
+    final line = stripComment(physical);
+    for (final ch in line.split('')) {
+      if (ch == '[' || ch == '{') depth++;
+      if (ch == ']' || ch == '}') depth--;
+      current += ch;
+    }
+    if (depth > 0) {
+      current += ' ';
+      continue;
+    }
+    if (current.trim().isNotEmpty) out.add(current.trim());
+    current = '';
+  }
+  if (current.trim().isNotEmpty) out.add(current.trim());
+  return out;
