+final _manifestPath = '$_repoRoot/docs/integrations/herdr/fa.toml';
+final _fixturesDir = '$_repoRoot/docs/integrations/herdr/fixtures';
+
+// ---------------------------------------------------------------------------
+// Minimal TOML reader for the manifest subset fa.toml uses. Anything else
