+      expect(_classifyFaScreen(manifest, busyWithGutter), 'working');
+
+      // A transcript that merely quotes `Working…` cannot outvote the resting
+      // gutter (150 > 100).
+      expect(
+        _classifyFaScreen(
+          manifest,
+          'the log said Working… and moved on\n╰─ \n',
