+  var current = '';
+  for (final physical in text.replaceAll('\r\n', '\n').split('\n')) {
+    final line = stripComment(physical);
+    for (final ch in line.split('')) {
+      if (ch == '[' || ch == '{') depth++;
+      if (ch == ']' || ch == '}') depth--;
