+).trimRight();
+
+String renderApprovalFixture() {
+  const request = ApprovalRequest(
+    toolName: 'bash',
+    tier: ApprovalTier.exec,
+    arguments: {'command': 'rm -rf ./build'},
+    reason: 'exec tier requires approval in mode: code',
+  );
