    final padded = tuiPadRight(tuiFitWidth(plain, termWidth), termWidth);
    if (padded.length <= frame.length + 1) return _dim(padded);
    return '${_accent2Plain(frame)} '
        '${_dim(padded.substring(frame.length + 1))}';
  }

