+
+String renderSecretFixture() {
+  const spec = SecretPromptSpec(
+    name: 'SERPAPI_KEY',
+    reason: 'the web_search tool needs a SerpApi key',
+  );
+  return '⠋ Working…      3s\n${_sheet(spec)}\n';
