    '   99s',
    '  100s',
    '  999s',
    ' 1000s',
  ]);
  // The trailing hint zone keeps its column.
  expect(
    rows.every(
      (row) => row.substring(hintCol) == rows.first.substring(hintCol),
    ),
    isTrue,
  );
});

