+  const _Gate(
+    this.contains,
+    this.regex,
+    this.lineRegex,
+    this.all,
+    this.any,
+    this.not,
+  );
+
+  /// `{ key = [values] }` — a single-key inline gate table.
+  factory _Gate.inline(String raw) {
+    final m = RegExp(r'^\{ (\w+) = \[(.*)\] \}$').firstMatch(raw.trim());
+    if (m == null) throw FormatException('unsupported gate shape: $raw');
