+String renderAskFixture() {
+  const spec = AskPromptSpec(
+    header: 'Ask',
+    question: 'Which database should the migration target?',
+    index: 0,
+    total: 1,
+    options: [
+      AskOption(label: 'Postgres', description: 'keeps the current host'),
