/// The busy row with escapes stripped — each character sits at its true
/// terminal column.
String busyRowOf(FaTuiModel model, {String marker = '· run'}) => model
    .view()
    .content
    .split('\n')
    .map((line) => line.replaceAll(ansi, ''))
    .firstWhere((line) => line.contains(marker));

